INSERT INTO notes (id, owner_sub, owner_name, title, body, excerpt, visibility, slug, accent, created_at, updated_at) VALUES
('7b1e5a40-0000-4000-8000-000000000001','seed','YOHAKU 編集部','余白について',E'書くことは、何かを足すことだと思われがちだ。けれど実際には、削ることのほうがずっと多い。\n\n## 白は、無ではない\n\n紙の白は、まだ書かれていない可能性の総量だ。行間、段落の切れ目、ページの端。そこに読み手の呼吸が入りこむ。\n\n> 余白とは、読む人のために残しておく席のことだ。\n\n## 三つの習慣\n\n- 一日の終わりに、三行だけ書く\n- 書いたものを翌朝に読み返す\n- 残す価値のある一文だけを、公開する\n\n静かな場所で考えたことは、たいてい長持ちする。','書くことは、何かを足すことだと思われがちだ。けれど実際には、削ることのほうがずっと多い。紙の白は、まだ書かれていない可能性の総量だ。','public','261016-seed01','shu', now() - interval '3 day', now() - interval '3 day'),
('7b1e5a40-0000-4000-8000-000000000002','seed','YOHAKU 編集部','サーバーが眠っているあいだに',E'このノートは、東京リージョンのサーバーレス環境で動いている。誰も読んでいない時間、サーバーは存在すらしない。\n\n## 眠りの設計\n\n最初の一人がページを開くと、環境が目を覚ます。二人目からは、もう起きている。\n\n```\nidle   → 0 environments\nfirst  → cold start (~2s)\nnext   → warm (~0.2s)\n```\n\n使われない時間に払わない、という設計は、どこか余白の考え方に似ている。','このノートは、東京リージョンのサーバーレス環境で動いている。誰も読んでいない時間、サーバーは存在すらしない。','public','261016-seed02','ai', now() - interval '2 day', now() - interval '2 day'),
('7b1e5a40-0000-4000-8000-000000000003','seed','YOHAKU 編集部','雨の日のメモ術',E'雨の日は、外の音がひとつの層になって、考えごとに向いている。\n\n## やり方\n\n1. 窓の外の音をひとつだけ書き留める\n2. その音から連想したことを三つ\n3. 三つのうち、明日も覚えていそうなものに印をつける\n\n書き留めた音は、読み返したときに、その日の空気ごと連れてくる。','雨の日は、外の音がひとつの層になって、考えごとに向いている。窓の外の音をひとつだけ書き留める。','public','261016-seed03','matcha', now() - interval '1 day', now() - interval '1 day'),
('7b1e5a40-0000-4000-8000-000000000004','seed','YOHAKU 編集部','一枚の紙で考える',E'ノートアプリは無限に書ける。だからこそ、あえて一枚に収める練習をする。\n\n## 制約は、形をくれる\n\n一枚に収めようとすると、言葉は自然と短くなり、順番が生まれる。順番が生まれると、考えに骨格ができる。\n\n> 長く書くのは簡単だ。短く書くには、時間がかかる。\n\n今日の考えを、一枚に。','ノートアプリは無限に書ける。だからこそ、あえて一枚に収める練習をする。制約は、形をくれる。','public','261016-seed04','kin', now() - interval '5 hour', now() - interval '5 hour');
